You are given a question that requires some input and output variables as follows:

In a strategic game, a player has a Pawn unit on the board. The Pawn has an ability called "arrowstorm" which can target an enemy unit within a certain range. Given the type of unit, the ability to be executed, and the coordinates of the target location, what is the outcome of the ability execution?

The input and output requirements are as follows:

Input:
  `unit_type` (str): The type of unit to be created. Possible values: "Pawn".
  `ability_name` (str): The name of the ability to be executed. Possible values: "arrowstorm".
  `target_x` (int): The x-coordinate of the target location.
  `target_y` (int): The y-coordinate of the target location.

Output:
  `return` (dict): A dictionary containing the result of the ability execution. The key is "result" and the value is a string describing the outcome of the ability.

Given the following input:

{'unit_type': 'Pawn', 'ability_name': 'arrowstorm', 'target_x': -1, 'target_y': -5}

Can you predict the output without writing any code? Please think and then provide the exact output in the form of a JSON value (object, array, number or string, or one of the following three literal names: false null true) as your final answer. The keys and values of the object should strictly match the output requirement as specified.

Tip: Here is a reference code snippet for this question. You can refer to this code to guide your reasoning but not copy spans of code directly.

# import necessary packages
import math
import random

# all class and function definitions in the code file, if any
class Unit:
    def __init__(self, strength, hp, xp_drops, level_up_xp, moves, cooldown, name, abilities, ability_functions, can_move):
        self.strength = strength
        self.hp = hp
        self.xp_drops = xp_drops
        self.level_up_xp = level_up_xp
        self.moves = moves
        self.cooldown = [0] * cooldown
        self.name = name
        self.abilities = abilities
        self.ability_functions = ability_functions
        self.can_move = can_move
        self.board = None
        self.side = None

    def set_board(self, board):
        self.board = board

    def set_side(self, side):
        self.side = side

    def get_side(self):
        return self.side

    def effective_strength(self):
        return self.strength

    def deal_damage(self, damage):
        self.hp -= damage

    def heal_damage(self, heal):
        self.hp += heal

    def buff_attack(self, buff, duration):
        pass

    def buff_health(self, buff, duration):
        pass

    def add_protected(self, unit):
        pass

    def check_move(self, x, y):
        return (x, y) in self.moves

    def qualify_move(self, move):
        return move

class Pawn(Unit):
    def __init__(self):
        moves = [(0, 1)]
        Unit.__init__(self, 3, 10, 1, 2, moves, 3, "Pawn", ["arrowstorm"], [self.arrowstorm], True)

    def arrowstorm(self, squares):
        target = self.board.get_unit(squares[0][0], squares[0][1])
        if self.cooldown[0] == 0:
            if target is not None:
                if not self.side == target.get_side():
                    xDifference = abs(self.board.get_loc(self)[0] - self.board.get_loc(target)[0])
                    yDifference = abs(self.board.get_loc(self)[1] - self.board.get_loc(target)[1])
                    if xDifference <= 2 and yDifference <= 2:
                        target.deal_damage(math.ceil(.75 * self.effective_strength()))
                        self.cooldown[0] = 8
                        return "arrowstorm"
                    else:
                        return "Target not in range."
                else:
                    return "No friendly fire."
            else:
                return "Target does not exist."
        else:
            return "Ability not sufficiently cooled down."

class Board:
    def __init__(self):
        self.units = {}

    def get_unit(self, x, y):
        return self.units.get((x, y), None)

    def get_loc(self, unit):
        for loc, u in self.units.items():
            if u == unit:
                return loc
        return None

    def move_unit(self, unit, dx, dy):
        loc = self.get_loc(unit)
        if loc:
            new_loc = (loc[0] + dx, loc[1] + dy)
            self.units[new_loc] = unit
            del self.units[loc]

    def add_unit(self, unit, x, y):
        self.units[(x, y)] = unit

# main function
def main_solution(unit_type, ability_name, target_x, target_y):
    # Initialize the board and units
    board = Board()
    unit_dict = {"Pawn": Pawn}

    # Create the unit
    unit = unit_dict[unit_type]()
    unit.set_board(board)
    unit.set_side("player")
    board.add_unit(unit, 0, 0)

    # Execute the ability
    ability_result = getattr(unit, ability_name)([(target_x, target_y)])

    # Return the result
    return {"result": ability_result}

