class LNode:
    def __init__(self, x, next=None):
        self._data = x
        self.next = next

class LList:
    def __init__(self, data=[]):
        self.head = None
        if data:
            data = list(data)
            for d in data:
                self.push(d)

    def is_empty(self):
        return self.head is None

    def push(self, x):
        if self.is_empty():
            self.head = LNode(x)
        else:
            node = self.head
            while node.next:
                node = node.next
            node.next = LNode(x)

