        if (NX is None and ResX is None) or (NX is not None and ResX is not None):
            raise GridError('Either NX or ResX must be given, but not both!')
        if Xmax < Xmin:
            self.Xmin, self.Xmax = Xmax, Xmin
        else:
            self.Xmin, self.Xmax = Xmin, Xmax

        if NX is not None:
            self.NX = NX
            self.ResX = (self.Xmax - self.Xmin) / NX
        else:
            self.ResX = ResX
            self.NX = int(np.floor((self.Xmax - self.Xmin) / ResX) + 2)

        self._X1D_ordered = np.linspace(self.Xmin, self.Xmax, self.NX)

    @property
    def X1D(self):
        return self._X1D_ordered

