class ShoppingCart:
    def __init__(self, promotional_rules):
        self.items = []
        self.promotional_rules = promotional_rules
        self.tours = {
            "OH": {"name": "Opera house tour", "price": 300.00},
            "BC": {"name": "Sydney Bridge Climb", "price": 110.00},
            "SK": {"name": "Sydney Sky Tower", "price": 30.00}
        }

    def add(self, tour_id):
        if tour_id in self.tours:
            self.items.append(tour_id)

    def total(self):
        total_price = 0.0
        tour_counts = {tour_id: self.items.count(tour_id) for tour_id in self.tours}

        # Apply 3 for 2 deal on Opera House tickets
        if tour_counts["OH"] >= 3:
            total_price += (tour_counts["OH"] // 3) * 2 * self.tours["OH"]["price"]
            total_price += (tour_counts["OH"] % 3) * self.tours["OH"]["price"]
        else:
            total_price += tour_counts["OH"] * self.tours["OH"]["price"]

        # Apply free Sky Tower tour with every Opera House tour
        total_price += tour_counts["SK"] * self.tours["SK"]["price"]
        if tour_counts["OH"] > 0:
            total_price -= min(tour_counts["OH"], tour_counts["SK"]) * self.tours["SK"]["price"]

        # Apply bulk discount on Sydney Bridge Climb
        if tour_counts["BC"] > 4:
            total_price += tour_counts["BC"] * (self.tours["BC"]["price"] - 20)
        else:
            total_price += tour_counts["BC"] * self.tours["BC"]["price"]

        return round(total_price, 2)

