            else:
                output_list.append(math.log2(top / bottom) + stdev / median)
        elif stat == "nad":
            output_list.append(normalized_degree(mean, vertices, max_degree, degree_threshold))

    return {"vertices": vertices, "edges": edges, "statistics": output_list}

